(()=>{const done={en:{person:['Request approved','Paraspara will now look for consent-safe capacity.'],giver:['Offer confirmed','We will notify you when a consented request matches this offer.'],steward:['Safety check confirmed','The case can continue with the verified safety conditions.'],lead:['Decision recorded','Paraspara will continue using your human decision.'],funder:['Funding confirmed','Only aggregate, identity-free outcomes will be reported.']},hi:{person:['अनुरोध मंज़ूर','Paraspara अब सुरक्षित सहयोग खोजेगा।'],giver:['प्रस्ताव पुष्ट','ज़रूरत मेल खाने पर हम आपको बताएँगे।'],steward:['सुरक्षा जाँच पुष्ट','पुष्ट शर्तों के साथ मामला आगे बढ़ सकता है।'],lead:['निर्णय दर्ज','Paraspara आपके निर्णय के अनुसार आगे बढ़ेगा।'],funder:['फंडिंग पुष्ट','सिर्फ़ पहचान-रहित नतीजे बताए जाएँगे।']},gu:{person:['વિનંતી મંજૂર','Paraspara હવે સુરક્ષિત સહયોગ શોધશે.'],giver:['પ્રસ્તાવ પુષ્ટ','જરૂર મેળ ખાશે ત્યારે અમે જાણ કરીશું.'],steward:['સુરક્ષા તપાસ પુષ્ટ','ખાતરી કરેલી શરતો સાથે કેસ આગળ વધી શકે છે.'],lead:['નિર્ણય નોંધાયો','Paraspara તમારા નિર્ણય મુજબ આગળ વધશે.'],funder:['ભંડોળ પુષ્ટ','ફક્ત ઓળખ વિનાના પરિણામ જણાવાશે.']}};const activeRole=()=>document.querySelector("[data-role][aria-pressed='true']")?.dataset.role||'person';function wire(){const form=document.getElementById('nativeConfirmForm'),button=document.getElementById('confirmAction'),id=localStorage.getItem('paraspara-case');if(!form||!button)return;button.onclick=null;button.onpointerup=null;button.onkeydown=null;button.disabled=false;delete button.dataset.busy;if(id)form.action='/api/cases/'+encodeURIComponent(id)+'/confirm/'+activeRole()}function showResult(role){const box=document.getElementById('backendActions'),button=document.getElementById('confirmAction'),edit=document.getElementById('editDraft'),message=document.getElementById('processingMessage'),lang=localStorage.getItem('paraspara-lang')||'en',text=(done[lang]||done.en)[role];if(!box||!text)return;button.hidden=true;edit.hidden=true;document.getElementById('completionState')?.remove();box.insertAdjacentHTML('afterbegin','<div class="completion-state" id="completionState" role="status"><span aria-hidden="true">✓</span><div><strong>'+text[0]+'</strong><p>'+text[1]+'</p></div></div>');box.style.display='block';document.getElementById('ai')?.classList.add('show');document.querySelector('.work')?.classList.add('reviewing','completed');if(message)message.textContent='Saved to the audit trail'}wire();const box=document.getElementById('backendActions');if(box)new MutationObserver(wire).observe(box,{childList:true,subtree:true});document.querySelectorAll('[data-role]').forEach(item=>item.addEventListener('click',()=>setTimeout(wire,0)));const confirmed=new URLSearchParams(location.search).get('confirmed');if(confirmed){document.querySelector('[data-role="'+confirmed+'"]')?.click();setTimeout(()=>{showResult(confirmed);document.querySelector('.work')?.scrollIntoView({behavior:'auto',block:'center'});history.replaceState(null,'',location.pathname+'#roles')},30)}})();

